using System.Windows.Media.Imaging;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.Calibration;
static class Program{
 static int checks;static void Check(bool value,string label){checks++;if(!value)throw new Exception(label);}
 [STAThread]static int Main(){try{Run();Console.WriteLine($"ReadCalibFile.ConfigurationChecks: {checks} checks passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run(){
  _=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var root=FindRoot();var output=Path.GetFullPath(Environment.GetEnvironmentVariable("READCALIBFILE_CONFIG_OUTPUT")??Path.Combine(root,"analysis/full-audit/read-calib-file/configuration"));Directory.CreateDirectory(output);
  using var evidence=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"docs/plugins/read-calib-file-evidence.json")));var rich=evidence.RootElement.GetProperty("fixtures").EnumerateArray().Single(f=>f.GetProperty("name").GetString()=="rich.xml").GetProperty("xml").GetString()!;var file=Path.Combine(output,"configuration-acceptance.xml");File.WriteAllText(file,rich);
  var plugin=new ReadCalibFilePlugin();using var scope=new ModuleExecutionScope();var values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());var node=new NodeDocument("read-model",ReadCalibFilePlugin.Id,"1.0.0","标定加载",values);var services=new Subscriptions();var events=new List<string>();var history=new ConfigurationFileHistory(Path.Combine(output,"history-"+Guid.NewGuid().ToString("N")));var selected=file;var fileService=new RecordingFiles(new WpfConfigurationFileService(history,(_,_)=>new(ConfigurationFileStatus.Selected,[selected])),events);int applied=0,ran=0;NodeRunRecord? last=null;
  var registry=new ModuleRegistry();new ToolPluginRegistry().Register(plugin,registry);
  var context=new ToolEditorContext(node,root,v=>{values=v;applied++;events.Add("apply");},async v=>{ran++;events.Add("run");var procedure=new ProcedureDocument("read-config","read",[node with{Parameters=v}],[]);var run=await new GraphExecutor(registry).RunAsync(procedure,root,scope:scope);return last=run.Nodes.Single();}){Scope=scope,ConfigurationFiles=fileService,ConfigurationNotifications=new WpfConfigurationNotificationService((_,notification)=>events.Add("notify:"+notification.Kind)),ConfigurationExecutionStatus=()=>new(false,false,true,false,true),ConfigurationSubscriptions=services};
  using var session=plugin.CreateConfiguration(context);Check(plugin is IToolConfigurationProvider,"model provider");Check(session.State.Definition.Tabs.Count==1,"source single page");Check(session.State.Find("SaveCalibDataEnable")!.Value=="True","native default read through adapter");Check(services.ReadNames.Contains("SnapImagePointX1")&&!services.ReadNames.Contains("SnapImagePointX"),"operation destination not caption");Check(!session.State.Diagnostics.Any(d=>d.Code=="UnsupportedOperation"),"source declared operations implemented: "+string.Join(";",session.State.Diagnostics.Select(d=>d.Operation+":"+d.Message)));
  var window=new ToolConfigurationModelWindow(context,session){ShowActivated=false,ShowInTaskbar=false,Left=-30000,Top=-30000};window.Show();window.UpdateLayout();Check(window.ConfigurationView.Diagnostics.Count==0,"all Read templates registered");Check(!window.ConfigurationView.TabHeadersVisible,"source single page header hidden");Check(Visuals(window).OfType<TextBox>().Any(t=>t.Name=="ReadCalibFilePath"),"source file picker leaf");Check(Visuals(window).OfType<ToolConfigurationSubscriptionSelector>().Count()==10,"source ten input subscription leaves");Check(Visuals(window).OfType<ReadCalibFileConfigurationPanel>().Count()==1,"special panel content extension");
  session.State.CommitUser("FilePath",file);window.UpdateLayout();Check(values["FilePath"].GetString()==file&&applied>0,"file commit applied");Check(values["OutputSchema"].GetString()!="[]","dynamic schema persisted");Check(Visuals(window).OfType<TextBox>().Count(t=>t.IsReadOnly)==72,"two point tables exactly 3columns");Check(Visuals(window).OfType<TextBlock>().Any(t=>t.Text==ConfigurationLocalization.ForLanguage("Chinese").Get("WorldPointLst")),"source localized dynamic field");Check(ran==1&&last?.Status==NodeRunStatus.Success,"automatic run uses actual GraphExecutor");Check(last!.Outputs["ModuStatus"].As<long>()==1,"graph publishes loaded calibration");
  Check(history.Get(ReadCalibFilePlugin.Id).Directory==null,"typed path does not change picker history");events.Clear();var choose=Visuals(window).OfType<Button>().Single(b=>b.Name=="ChooseReadCalibFile");choose.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(events.SequenceEqual(new[]{"select","apply","notify:Success","run","history"}),"source picker success order including repeated same path: "+string.Join(",",events));Check(history.Get(ReadCalibFilePlugin.Id).Directory==Path.GetFullPath(output),"picker history persisted after commit/run: "+history.Get(ReadCalibFilePlugin.Id)+" vs "+output);
  var malformedDirectory=Path.Combine(output,"bad-selection");Directory.CreateDirectory(malformedDirectory);selected=Path.Combine(malformedDirectory,"bad.xml");File.WriteAllText(selected,"broken");events.Clear();choose.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(events.SequenceEqual(new[]{"select","notify:Error","history"}),"source failed load selection still remembers after notification");Check(history.Get(ReadCalibFilePlugin.Id).Directory==Path.GetFullPath(malformedDirectory),"failed parse selected directory remembered");selected=file;
  var previous=values["OutputSchema"].GetString();session.State.CommitUser("FilePath",Path.Combine(output,"absent.xml"));Check(session.State.Find("FilePath")!.Value==Path.Combine(output,"absent.xml")&&values["FilePath"].GetString()==file,"native file error retains attempted model value and old native document path");Check(values["OutputSchema"].GetString()==previous,"failed file retains schema");Check(session.State.Diagnostics.Any(d=>d.Code=="OperationError"),"source load failure visible diagnostic");
  session.State.CommitUser("FilePath","");window.UpdateLayout();Check(values["FilePath"].GetString()==""&&last!.Outputs["ModuStatus"].As<long>()==0,"clear file resets execution data");Check(Visuals(window).OfType<TextBox>().Count(t=>t.IsReadOnly)==72,"ReadData whitespace retains source panel contents");session.State.CommitUser("FilePath",file);
  session.State.CommitUser("SaveCalibDataEnable","False");Check(!values["SaveCalibDataEnable"].GetBoolean(),"save enable through adapter");
  var selector=Visuals(window).OfType<ToolConfigurationSubscriptionSelector>().First();var binding=new ConfigurationSubscriptionBinding(new ConfigurationConstantReference("int","1"),ConfigurationSubscriptionIndex.All);Check(selector.Bind(binding),"typed selector bind");Check(services.LastBinding==binding,"typed identity reaches service");
  var bitmap=new RenderTargetBitmap(420,500,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(output,"source-derived-read-model.png")))encoder.Save(stream);
  var scroller=Visuals(window.ConfigurationView.Tabs).OfType<ScrollViewer>().First();scroller.ScrollToBottom();window.UpdateLayout();var pointsBitmap=new RenderTargetBitmap(420,500,96,96,PixelFormats.Pbgra32);pointsBitmap.Render(window);var pointsEncoder=new PngBitmapEncoder();pointsEncoder.Frames.Add(BitmapFrame.Create(pointsBitmap));using(var stream=File.Create(Path.Combine(output,"source-derived-read-model-points.png")))pointsEncoder.Save(stream);
  session.State.PersistSubscriptionMode(session.State.Find("SaveCalibDataEnable")!,true);using(var store=JsonDocument.Parse(values["ConfigurationUserData"].GetString()!))Check(store.RootElement.GetProperty("@SaveCalibDataEnable").GetString()=="True","separate UI user-data persisted");session.State.PersistSubscriptionMode(session.State.Find("SaveCalibDataEnable")!,false);
  bool closed=false;session.CloseRequested+=()=>closed=true;session.State.Invoke(session.State.Nodes.Single(n=>n.CaptionKey=="Confirm"));Check(closed,"source close command route");window.Close();
  var remoteValues=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());remoteValues["FilePath"]=JsonSerializer.SerializeToElement(file);remoteValues["OutputSchema"]=JsonSerializer.SerializeToElement(ReadCalibFilePlugin.Schema(ReadCalibFileData.Parse(rich).Data!));var remoteNode=new NodeDocument("read-remote-mock",ReadCalibFilePlugin.Id,"1.0.0","标定加载",remoteValues);var remoteFiles=new RemoteFiles(file);int remoteRuns=0;var remoteContext=context with{Node=remoteNode,IsRemoteMode=true,ConfigurationFiles=remoteFiles,Apply=v=>remoteValues=v,Run=_=>{remoteRuns++;return Task.FromResult(new NodeRunRecord(remoteNode.Id,NodeRunStatus.Success,new Dictionary<string,PortValue>(),0));}};using(var remoteSession=plugin.CreateConfiguration(remoteContext)){var remoteWindow=new ToolConfigurationModelWindow(remoteContext,remoteSession){ShowActivated=false,ShowInTaskbar=false,Left=-30000,Top=-30000};remoteWindow.Show();remoteWindow.UpdateLayout();Visuals(remoteWindow).OfType<Button>().Single(b=>b.Name=="ChooseReadCalibFile").RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(remoteFiles.Request is {Remote:true}&&remoteFiles.Request.ModuleKey==ReadCalibFilePlugin.Id,"remote context reaches the existing configuration file service");Check(remoteFiles.Request!.CurrentPath==file&&remoteFiles.Request.Filter.Contains("*.xml",StringComparison.OrdinalIgnoreCase),"remote picker receives current file path and XML filter");Check(remoteValues["FilePath"].GetString()==file&&remoteRuns==1,"mock remote selection flows through commit and execution");remoteWindow.Close();}
  Check(new WpfConfigurationFileService(history).Select(null,new(ReadCalibFilePlugin.Id,"","*.xml|*.xml","open",Remote:true)).Status==ConfigurationFileStatus.Unsupported,"default local picker explicitly rejects unavailable remote backend");
  var missingContext=context with{Node=node with{Id="read-missing-service"},ConfigurationSubscriptions=null};using var missing=plugin.CreateConfiguration(missingContext);Check(missing.State.Diagnostics.Any(d=>d.Message.Contains("service is unavailable")),"missing subscription service explicit");
  foreach(var host in new[]{new ConfigurationExecutionHostStatus(true,false,true,false,true),new(false,false,false,false,true),new(false,false,true,true,true),new(false,false,true,false,false)}){var blockedContext=context with{Node=node with{Id="blocked-"+checks},ConfigurationExecutionStatus=()=>host};using var blocked=plugin.CreateConfiguration(blockedContext);var prior=ran;blocked.State.Invoke(blocked.State.Find("Execute")!);Check(ran==prior,"host status blocks graph dispatch");Check(blocked.State.Diagnostics.Any(d=>d.Code=="OperationError"),"host rejection explicit");}
  using var noExecution=plugin.CreateConfiguration(context with{Node=node with{Id="missing-execution"},ConfigurationExecutionStatus=null});var beforeMissing=ran;noExecution.State.Invoke(noExecution.State.Find("Execute")!);Check(ran==beforeMissing,"missing execution status is not guessed ready");
  var rejectedContext=context with{Node=node with{Id="refused-document-write"},Apply=_=>throw new InvalidOperationException("controlled host write rejection")};
  using var rejected=plugin.CreateConfiguration(rejectedContext);var beforeRejected=ran;
  rejected.State.CommitUser("FilePath",file);
  Check(rejected.State.Find("FilePath")!.Value==""&&rejected.State.Diagnostics.Any(d=>d.Message.Contains("controlled host write rejection")),"Refused file/schema document write is diagnosed and restores model value");
  Check(plugin.Snapshot(rejectedContext).Data.Outputs.Count==0&&ran==beforeRejected,"Refused file write preserves runtime data and does not dispatch automatic execution");
  rejected.State.CommitUser("SaveCalibDataEnable","False");rejected.State.Initialize();
  Check(rejected.State.Find("SaveCalibDataEnable")!.Value=="True","Rejected host parameter write does not replace the adapter's accepted local parameter snapshot");
 }
 static string FindRoot(){var dir=new DirectoryInfo(AppContext.BaseDirectory);while(dir!=null&&!File.Exists(Path.Combine(dir.FullName,"docs/PARALLEL-WORK.md")))dir=dir.Parent;return dir!.FullName;}
 static IEnumerable<DependencyObject> Visuals(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var node in Visuals(VisualTreeHelper.GetChild(root,i)))yield return node;}
 sealed class RecordingFiles(IToolConfigurationFileService inner,List<string> events):IToolConfigurationFileService{
  public ConfigurationFileSelection Select(Window? owner,ConfigurationFileRequest request){events.Add("select");return inner.Select(owner,request);}
  public ConfigurationFileHistoryResult Remember(string moduleKey,string file){events.Add("history");return inner.Remember(moduleKey,file);}
 }
 sealed class RemoteFiles(string selected):IToolConfigurationFileService{public ConfigurationFileRequest? Request;public ConfigurationFileSelection Select(Window? owner,ConfigurationFileRequest request){Request=request;return new(ConfigurationFileStatus.Selected,[selected]);}public ConfigurationFileHistoryResult Remember(string moduleKey,string selectedFile)=>new(true,Path.GetDirectoryName(selectedFile));}
 sealed class Subscriptions:IToolConfigurationSubscriptionService{
  public HashSet<string> ReadNames=[];public ConfigurationSubscriptionBinding? LastBinding;
  public ConfigurationSubscriptionTreeResult Enumerate(ConfigurationSubscriptionQuery query)=>new(ConfigurationSubscriptionStatus.Available,[]);
  public ConfigurationSubscriptionBindingResult Read(ConfigurationSubscriptionDestination d){ReadNames.Add(d.Name);return new(ConfigurationSubscriptionStatus.Available,null,"");}
  public ConfigurationSubscriptionBindingResult Bind(ConfigurationSubscriptionDestination d,ConfigurationSubscriptionBinding? binding){LastBinding=binding;return new(ConfigurationSubscriptionStatus.Available,binding,binding is null?"":"1");}
 }
